function getExitWinningSide({ inContextDrawMatchUps, drawPosition, matchUpId }) {
    const sourceMatchUps = inContextDrawMatchUps
        .filter(({ winnerMatchUpId, loserMatchUpId }) => loserMatchUpId === matchUpId || winnerMatchUpId === matchUpId)
        .sort((a, b) => a.roundPosition - b.roundPosition);
    const matchUp = inContextDrawMatchUps.find((matchUp) => matchUp.matchUpId === matchUpId);
    const targetSide = matchUp?.sides?.find((side) => side.drawPosition === drawPosition);
    if (targetSide?.bye)
        return undefined;
    const feedRound = matchUp.feedRound;
    if (feedRound)
        return targetSide?.sideNumber ?? 1;
    const participantId = targetSide?.participantId;
    return sourceMatchUps.reduce((sideNumber, sourceMatchUp, index) => {
        const fedFromHere = sourceMatchUp.structureId === matchUp?.structureId
            ? sourceMatchUp.drawPositions?.includes(drawPosition)
            : !!participantId && sourceMatchUp.sides?.some((side) => side.participantId === participantId);
        return fedFromHere ? index + 1 : sideNumber;
    }, undefined);
}

export { getExitWinningSide };
