import { getParticipants } from '../../query/participants/getParticipants.mjs';
import { requireParams } from '../../helpers/parameters/requireParams.mjs';
import { definedAttributes } from '../../tools/definedAttributes.mjs';
import { makeDeepCopy } from '../../tools/makeDeepCopy.mjs';
import { addParticipant } from './addParticipant.mjs';
import { UUID } from '../../tools/UUID.mjs';
import { MISSING_VALUE, INVALID_VALUES, INVALID_PARTICIPANT_TYPE } from '../../constants/errorConditionConstants.mjs';
import { INDIVIDUAL, GROUP } from '../../constants/participantConstants.mjs';
import { TOURNAMENT_RECORD } from '../../constants/attributeConstants.mjs';
import { SUCCESS } from '../../constants/resultConstants.mjs';
import { OTHER } from '../../constants/participantRoleValues.mjs';

function createGroupParticipant({ individualParticipantIds = [], participantRoleResponsibilities, participantRole = OTHER, tournamentRecord, participantId, groupName, }) {
    const paramsCheck = requireParams({ tournamentRecord }, [TOURNAMENT_RECORD]);
    if (paramsCheck.error)
        return paramsCheck;
    if (!groupName)
        return { error: MISSING_VALUE, info: 'Missing groupName' };
    if (!Array.isArray(individualParticipantIds))
        return {
            info: 'Invalid individualParticipantIds',
            error: INVALID_VALUES,
        };
    const participants = getParticipants({
        participantFilters: { participantTypes: [INDIVIDUAL] },
        tournamentRecord,
    }).participants ?? [];
    const tournamentIndividualParticipantIds = participants.map((participant) => participant.participantId);
    for (const participantId of individualParticipantIds) {
        if (!tournamentIndividualParticipantIds.includes(participantId)) {
            return { error: INVALID_PARTICIPANT_TYPE, participantId };
        }
    }
    const groupParticipant = definedAttributes({
        participantId: participantId || UUID(),
        participantRoleResponsibilities,
        participantName: groupName,
        individualParticipantIds,
        participantType: GROUP,
        participantRole,
    });
    const result = addParticipant({
        participant: groupParticipant,
        tournamentRecord,
    });
    if (result.error)
        return result;
    return { ...SUCCESS, participant: makeDeepCopy(groupParticipant) };
}

export { createGroupParticipant };
