function getUnfilledPositions({ drawPositionGroups, positionAssignments }) {
    const assignmentMap = Object.assign({}, ...positionAssignments.map((assignment) => ({
        [assignment.drawPosition]: assignment,
    })));
    return drawPositionGroups
        .map((drawPositions) => {
        return drawPositions
            .filter(Boolean)
            .map((drawPosition) => assignmentMap[drawPosition])
            .filter(Boolean)
            .filter((assignment) => !assignment.participantId && !assignment.bye)
            .map((assignment) => assignment.drawPosition);
    })
        .flat()
        .filter(Boolean);
}

export { getUnfilledPositions };
