import { PayloadProfileEnum } from '../../types/tournamentTypes.mjs';
import { tallyParticipantResults } from '../matchUps/roundRobinTally/tallyParticipantResults.mjs';
import { getStructureSeedAssignments } from '../structure/getStructureSeedAssignments.mjs';
import { getAllStructureMatchUps } from '../matchUps/getAllStructureMatchUps.mjs';
import { getPositionAssignments } from './positionsGetter.mjs';
import { getEventPublishStatus } from '../event/getEventPublishStatus.mjs';
import { getDrawIsPublished } from '../publishing/getDrawIsPublished.mjs';
import { getStructureGroups } from '../structure/getStructureGroups.mjs';
import { firstClassOrExtension } from '../../acquire/firstClassOrExtension.mjs';
import { createSubOrderMap } from '../structure/createSubOrderMap.mjs';
import { structuresOf, matchUpsOf } from '../../acquire/structureMembers.mjs';
import { getPublishState } from '../publishing/getPublishState.mjs';
import { isVisiblyPublished } from '../publishing/isEmbargoed.mjs';
import { structureSort } from '../../functions/sorters/structureSort.mjs';
import { teamLevelMatchUps } from '../../acquire/teamLevelMatchUps.mjs';
import { findExtension } from '../../acquire/findExtension.mjs';
import { findStructure } from '../../acquire/findStructure.mjs';
import { makeDeepCopy } from '../../tools/makeDeepCopy.mjs';
import { xa } from '../../tools/extractAttributes.mjs';
import { MAIN, QUALIFYING, CONSOLATION, PLAY_OFF } from '../../constants/drawDefinitionConstants.mjs';
import { PARTICIPANT_ID } from '../../constants/attributeConstants.mjs';
import { DISPLAY, TALLY } from '../../constants/extensionConstants.mjs';
import { PUBLIC_DISPLAY } from '../../constants/displayConstants.mjs';
import { TEAM_MATCHUP } from '../../constants/matchUpTypes.mjs';
import { PUBLIC } from '../../constants/timeItemConstants.mjs';
import { SUCCESS } from '../../constants/resultConstants.mjs';
import { INVALID_VALUES, MISSING_DRAW_DEFINITION, UNLINKED_STRUCTURES } from '../../constants/errorConditionConstants.mjs';
import { completedMatchUpStatuses } from '../../constants/matchUpStatusConstants.mjs';
import { DOUBLE_WALKOVER, DOUBLE_DEFAULT, IN_PROGRESS, COMPLETED, CANCELLED, DEFAULTED, RETIRED, WALKOVER, BYE } from '../../constants/matchUpStatusValues.mjs';

function getDrawData(params) {
    const { tournamentParticipants = [], includePositionAssignments, policyDefinitions, tournamentRecord, inContext = true, usePublishState, status = PUBLIC, pressureRating, refreshResults, contextProfile, drawDefinition, noDeepCopy, sortConfig, context, event, structuresProfile = PayloadProfileEnum.FULL, } = params;
    if (!Object.values(PayloadProfileEnum).includes(structuresProfile)) {
        return { error: INVALID_VALUES };
    }
    if (!drawDefinition)
        return { error: MISSING_DRAW_DEFINITION };
    const { matchUpFormat, updatedAt, drawType, drawName, drawId } = drawDefinition;
    const drawInfo = {
        matchUpFormat,
        updatedAt,
        drawName,
        drawType,
        drawId,
    };
    drawInfo.display = findExtension({ element: drawDefinition, name: DISPLAY }).extension?.value;
    const qualificationStageSeedAssignments = {};
    let mainStageSeedAssignments, report;
    const { allStructuresLinked, sourceStructureIds, hasDrawFeedProfile, structureGroups } = getStructureGroups({
        drawDefinition,
    });
    if (!allStructuresLinked)
        return { error: UNLINKED_STRUCTURES };
    const eventPublishState = params?.eventPublishState ?? getPublishState({ event }).publishState;
    const publishStatus = params?.publishStatus ?? getEventPublishStatus({ event, status });
    const drawDetails = eventPublishState?.status?.drawDetails?.[drawDefinition.drawId];
    const eventPublished = !!eventPublishState?.status?.published;
    const structureDetails = drawDetails?.structureDetails;
    let drawActive = false;
    let participantPlacements = false;
    const buildStructureStub = (structureId) => {
        const { structure } = findStructure({ drawDefinition, structureId });
        const leafMatchUps = (function collect(structs) {
            return (structs ?? []).flatMap((st) => {
                const contained = structuresOf(st);
                return contained?.length ? collect(contained) : (matchUpsOf(st) ?? []);
            });
        })(structure ? [structure] : []);
        const completedStatuses = [...completedMatchUpStatuses, BYE];
        const displaySettings = findExtension({ element: structure, name: DISPLAY }).extension?.value;
        return {
            stageSequence: structure?.stageSequence,
            structureName: structure?.structureName,
            structureType: structure?.structureType,
            finishingPosition: structure?.finishingPosition,
            matchUpFormat: structure?.matchUpFormat,
            stage: structure?.stage,
            display: displaySettings?.[PUBLIC_DISPLAY] ?? displaySettings,
            structureActive: leafMatchUps.some((matchUp) => !!matchUp?.winningSide || !!matchUp?.score?.scoreStringSide1 || matchUp?.matchUpStatus === BYE),
            structureCompleted: leafMatchUps.length > 0 && leafMatchUps.every((matchUp) => completedStatuses.includes(matchUp?.matchUpStatus)),
            structureId,
        };
    };
    const groupedStructures = structureGroups.map((structureIds) => {
        if (structuresProfile === PayloadProfileEnum.STUBS)
            return structureIds.map(buildStructureStub);
        const completedStructures = {};
        const structures = structureIds
            .map((structureId) => {
            const { structure } = findStructure({ drawDefinition, structureId });
            const { seedAssignments } = getStructureSeedAssignments({
                drawDefinition,
                structure,
            });
            if (structure?.stage === MAIN && structure.stageSequence === 1) {
                mainStageSeedAssignments = seedAssignments;
            }
            if (structure?.stage === QUALIFYING) {
                qualificationStageSeedAssignments[structure.stageSequence ?? 0] = seedAssignments;
            }
            return structure;
        })
            .sort((a, b) => structureSort(a, b, sortConfig))
            .map((structure) => {
            if (!structure)
                return undefined;
            const structureId = structure?.structureId;
            let seedAssignments = [];
            if (structure.stage && [MAIN, CONSOLATION, PLAY_OFF].includes(structure.stage)) {
                seedAssignments = mainStageSeedAssignments;
            }
            if (structure?.stage === QUALIFYING) {
                seedAssignments = qualificationStageSeedAssignments[structure.stageSequence ?? 0];
            }
            const { matchUps, roundMatchUps, roundProfile } = getAllStructureMatchUps({
                seedAssignments: structure?.seedAssignments?.length ? undefined : seedAssignments,
                context: { drawId: drawInfo.drawId, ...context },
                hydrateParticipants: params.hydrateParticipants,
                participantsProfile: params.participantsProfile,
                tournamentParticipants,
                policyDefinitions,
                tournamentRecord,
                usePublishState,
                publishStatus,
                contextProfile,
                drawDefinition,
                inContext,
                structure,
                event,
            });
            const { positionAssignments } = getPositionAssignments({ structure });
            let participantResults = positionAssignments?.filter(xa(PARTICIPANT_ID)).map((assignment) => {
                const participantResult = firstClassOrExtension({ element: assignment, attribute: 'tally', name: TALLY });
                const { drawPosition, participantId } = assignment;
                participantPlacements = true;
                return {
                    participantResult,
                    participantId,
                    drawPosition,
                };
            });
            if (matchUps.length &&
                ((!participantResults?.length && params.allParticipantResults) ||
                    (refreshResults && !structuresOf(structure)))) {
                const { subOrderMap } = createSubOrderMap({ positionAssignments });
                const hasTeamMatchUps = matchUps.some((matchUp) => matchUp.matchUpType === TEAM_MATCHUP);
                const consideredMatchUps = hasTeamMatchUps
                    ? matchUps.filter((matchUp) => matchUp.matchUpType === TEAM_MATCHUP)
                    : matchUps;
                const result = tallyParticipantResults({
                    matchUpFormat: structure.matchUpFormat,
                    matchUps: consideredMatchUps,
                    policyDefinitions,
                    pressureRating,
                    subOrderMap,
                });
                report = result?.report;
                participantResults = positionAssignments?.filter(xa(PARTICIPANT_ID)).map((assignment) => {
                    const { drawPosition, participantId } = assignment;
                    participantPlacements = true;
                    return {
                        participantResult: participantId && result?.participantResults?.[participantId],
                        participantId,
                        drawPosition,
                    };
                });
            }
            const structureInfo = structure
                ? {
                    stageSequence: structure.stageSequence,
                    structureName: structure.structureName,
                    structureType: structure.structureType,
                    finishingPosition: structure.finishingPosition,
                    matchUpFormat: structure.matchUpFormat,
                    stage: structure.stage,
                }
                : {};
            const displaySettings = findExtension({ element: structure, name: DISPLAY }).extension?.value;
            structureInfo.display = displaySettings?.[PUBLIC_DISPLAY] ?? displaySettings;
            structureInfo.sourceStructureIds = sourceStructureIds[structureId];
            structureInfo.hasDrawFeedProfile = hasDrawFeedProfile[structureId];
            structureInfo.positionAssignments = positionAssignments;
            structureInfo.structureActive = matchUps.reduce((active, matchUp) => {
                const structureActiveStatuses = [
                    DOUBLE_WALKOVER,
                    DOUBLE_DEFAULT,
                    IN_PROGRESS,
                    COMPLETED,
                    CANCELLED,
                    DEFAULTED,
                    RETIRED,
                    WALKOVER,
                ].includes(matchUp.matchUpStatus);
                return active || structureActiveStatuses || !!matchUp.winningSide || !!matchUp.score?.scoreStringSide1;
            }, false);
            const structureCompleted = teamLevelMatchUps(matchUps).every((matchUp) => [...completedMatchUpStatuses, BYE].includes(matchUp.matchUpStatus));
            structureInfo.structureCompleted = structureCompleted;
            completedStructures[structureId] = structureCompleted;
            if (structureInfo.structureActive)
                drawActive = true;
            return {
                ...structureInfo,
                participantResults,
                seedAssignments,
                roundMatchUps,
                roundProfile,
                structureId,
                report,
            };
        });
        structures.forEach((structure) => {
            if (!includePositionAssignments)
                delete structure.positionAssignments;
            structure.sourceStructuresComplete = structure.sourceStructureIds?.every((id) => completedStructures[id]);
        });
        return structures;
    });
    const structures = groupedStructures.flat().filter((structure) => {
        if (!usePublishState)
            return true;
        const structureDetail = structureDetails?.[structure?.structureId];
        return structureDetail ? isVisiblyPublished(structureDetail) : true;
    });
    drawInfo.drawActive = drawActive;
    drawInfo.participantPlacements = participantPlacements;
    drawInfo.drawGenerated = structures?.reduce((generated, structure) => {
        return generated || !!structure?.roundMatchUps;
    }, false);
    drawInfo.drawCompleted = structures?.reduce((completed, structure) => completed && structure.structureCompleted, true);
    drawInfo.drawPublished = usePublishState
        ? eventPublished && getDrawIsPublished({ publishStatus, drawId: drawInfo.drawId })
        : undefined;
    return {
        structures: !usePublishState || drawInfo.drawPublished
            ? (noDeepCopy && structures) || makeDeepCopy(structures, false, true)
            : undefined,
        drawInfo: noDeepCopy ? drawInfo : makeDeepCopy(drawInfo, false, true),
        ...SUCCESS,
    };
}

export { getDrawData };
