        tournamentRecords,
        remainingScheduleTimes,
        startTime: extractTime(startTime),
        endTime: extractTime(endTime),
        scheduleDate: extractDate(scheduleDate),
        averageMatchUpMinutes,
        clearScheduleDates,
        periodLength,
        venueIds,
