import { checkRequiredParameters } from '../../../../../helpers/parameters/checkRequiredParameters.mjs';
import { addExtension } from '../../../../extensions/addExtension.mjs';
import { findParticipant } from '../../../../../acquire/findParticipant.mjs';
import { TOURNAMENT_RECORDS } from '../../../../../constants/attributeConstants.mjs';
import { PERSON_REQUESTS } from '../../../../../constants/extensionConstants.mjs';
import { SUCCESS } from '../../../../../constants/resultConstants.mjs';

function savePersonRequests(params) {
    const { tournamentRecords, personRequests } = params;
    const paramsCheck = checkRequiredParameters(params, [{ [TOURNAMENT_RECORDS]: true }]);
    if (paramsCheck.error)
        return paramsCheck;
    if (!personRequests)
        return { ...SUCCESS };
    const tournaments = Object.values(tournamentRecords);
    for (const tournamentRecord of tournaments) {
        const tournamentParticipants = tournamentRecord.participants ?? [];
        const relevantPersonRequests = [];
        for (const personId of Object.keys(personRequests)) {
            if (findParticipant({ tournamentParticipants, personId })) {
                const requests = personRequests[personId];
                if (requests.length)
                    relevantPersonRequests.push({ personId, requests });
            }
        }
        if (Object.keys(relevantPersonRequests).length) {
            const extension = {
                value: relevantPersonRequests,
                name: PERSON_REQUESTS,
            };
            addExtension({ element: tournamentRecord, extension });
        }
    }
    return { ...SUCCESS };
}

export { savePersonRequests };
